import json
import subprocess
import sys
import tempfile
import tomllib
import unittest
from pathlib import Path

from artifacts import detect, project

from . import ROOT

EXAMPLE = ROOT / 'mason.toml.example'
SCRIPT = ROOT / 'bin' / 'artifact'

COMPILED = """#
# This file is autogenerated by pip-compile with Python 3.12
# by the following command:
#
#    pip-compile requirements/base.in
#
django==5.2.8
    # via -r requirements/base.in
"""


def example(**overrides: object) -> dict:
    base = tomllib.loads(EXAMPLE.read_text(encoding='utf-8'))
    base.pop('version')  # read_file checks it and removes it before the contents are checked
    for key, value in overrides.items():
        if value is ...:
            base.pop(key)
        else:
            base[key] = value
    return base


class FileCheckTests(unittest.TestCase):
    def test_example_states_the_current_version(self) -> None:
        text = EXAMPLE.read_text(encoding='utf-8')
        self.assertEqual(tomllib.loads(text)['version'], project.CONFIG_VERSION)

    def test_example_is_complete(self) -> None:
        self.assertEqual(project.check(example(), tuple(project.SECTIONS)), [])

    def test_every_section_is_optional_in_the_file(self) -> None:
        self.assertEqual(project.check({}), [])
        self.assertEqual(project.check({'limits': {'open_agent_prs': 5}}), [])

    def test_unknown_sections_and_keys(self) -> None:
        errors = project.check(example(deploy={}, limits={'open_agent_prs': 3, 'max_prs': 1}))
        self.assertTrue(any(e.startswith('$.deploy: is not a known field') for e in errors))
        self.assertTrue(any(e.startswith('$.limits.max_prs: is not a known field') for e in errors))

    def test_types(self) -> None:
        errors = project.check({'limits': {'open_agent_prs': '3'}, 'verify': {'exclusive': 'yes'}})
        self.assertIn('$.limits.open_agent_prs: must be an integer, got string', errors)
        self.assertIn('$.verify.exclusive: must be true or false, got string', errors)

    def test_pip_needs_a_compile_command_once_required(self) -> None:
        upgrades = {'pip_requirements': ['requirements/base.txt'], 'pip_sources': []}
        upgrades['npm_projects'] = []
        config = example(**{'dependency-upgrades': upgrades})
        self.assertEqual(project.check(config), [])
        self.assertIn(
            '$.dependency-upgrades.pip_compile: is required with pip_requirements',
            project.check(config, ('dependency-upgrades',)),
        )


class HeaderTests(unittest.TestCase):
    def test_command(self) -> None:
        self.assertTrue(detect.is_compiled(COMPILED))
        self.assertEqual(detect.header_command(COMPILED), 'pip-compile requirements/base.in')

    def test_command_written_as_a_prompt(self) -> None:
        text = (
            '# This file was autogenerated by uv via the following command:\n#    $ make compile\n'
        )
        self.assertEqual(detect.header_command(text), 'make compile')

    def test_uv(self) -> None:
        text = (
            '# This file was autogenerated by uv via the following command:\n'
            '#    uv pip compile x.in\n'
        )
        self.assertTrue(detect.is_compiled(text))
        self.assertEqual(detect.header_command(text), 'uv pip compile x.in')

    def test_hand_written_file(self) -> None:
        self.assertFalse(detect.is_compiled('django>=5\nrequests\n'))

    def test_remote_urls(self) -> None:
        for url in (
            'git@github.com:owner/repo.git',
            'https://github.com/owner/repo',
            'https://github.com/owner/repo.git',
            'ssh://git@github.com/owner/repo.git',
        ):
            match = detect.GITHUB_REMOTE.match(url)
            self.assertIsNotNone(match, url)
            self.assertEqual(match.group(1), 'owner/repo', url)
        self.assertIsNone(detect.GITHUB_REMOTE.match('git@gitlab.com:owner/repo.git'))


class ResolveTests(unittest.TestCase):
    """A real git repository with no configuration file."""

    def setUp(self) -> None:
        self._tmp = tempfile.TemporaryDirectory()
        self.repo = Path(self._tmp.name)
        self.git('init', '-q', '-b', 'trunk')
        self.git('remote', 'add', 'origin', 'git@github.com:owner/repo.git')
        self.write('requirements/base.in', 'django\n')
        self.write('requirements/base.txt', COMPILED)
        self.write('requirements/docs.txt', 'sphinx\n')  # not compiled
        self.write('package.json', json.dumps({'scripts': {'build': 'vite build'}}))
        self.write('package-lock.json', '{}')
        self.write('web/package-lock.json', '{}')
        self.write('web/node_modules/x/package-lock.json', '{}')
        self.write('.github/workflows/test.yml', 'on: pull_request\n')
        self.write('.gitignore', '.env\n')
        self.write('.env', 'SECRET=\n')
        self.git('add', '-f', '.', ':!.env')
        self.git('commit', '-q', '-m', 'base')
        self.git('update-ref', 'refs/remotes/origin/trunk', 'HEAD')
        self.git('symbolic-ref', 'refs/remotes/origin/HEAD', 'refs/remotes/origin/trunk')

    def tearDown(self) -> None:
        self._tmp.cleanup()

    def git(self, *args: str) -> None:
        identity = ['-c', 'user.name=t', '-c', 'user.email=t@example.com']
        subprocess.run(['git', '-C', str(self.repo), *identity, *args], check=True)

    def write(self, name: str, text: str) -> None:
        path = self.repo / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding='utf-8')

    def test_detects_everything_dependency_upgrades_needs(self) -> None:
        config = project.load(self.repo, 'dependency-upgrades')
        self.assertEqual(config['repo'], {'name': 'owner/repo', 'main_branch': 'trunk'})
        self.assertEqual(config['verify']['worktree_copy'], ['.env'])
        self.assertTrue(config['verify']['exclusive'])
        self.assertTrue(config['verify']['ci'])
        upgrades = config['dependency-upgrades']
        self.assertEqual(upgrades['pip_requirements'], ['requirements/base.txt'])
        self.assertEqual(upgrades['pip_sources'], ['requirements/base.in'])
        self.assertEqual(upgrades['pip_compile'], 'pip-compile requirements/base.in')
        self.assertEqual(upgrades['npm_projects'], ['.', 'web'])
        self.assertEqual(upgrades['npm_build'], 'npm run build')
        self.assertNotIn('verify', upgrades)

    def test_no_ci(self) -> None:
        self.git('rm', '-q', '.github/workflows/test.yml')
        resolved = project.resolve(self.repo)
        self.assertFalse(resolved.config['verify']['ci'])
        self.assertEqual(resolved.sources[('verify', 'ci')], 'default')

    def test_sources(self) -> None:
        resolved = project.resolve(self.repo)
        self.assertEqual(resolved.sources[('limits', 'open_agent_prs')], 'default')
        self.assertTrue(resolved.sources[('repo', 'name')].startswith('detected: '))
        self.assertFalse(resolved.file_exists)

    def test_file_wins_key_by_key(self) -> None:
        self.write(
            'mason.toml',
            'version = 1\n[limits]\nopen_agent_prs = 1\n\n[dependency-upgrades]\nnpm_projects = []\n',
        )
        resolved = project.resolve(self.repo)
        self.assertEqual(resolved.config['limits'], {'open_agent_prs': 1, 'stale_after_days': 14})
        self.assertEqual(resolved.sources[('limits', 'open_agent_prs')], 'file')
        upgrades = resolved.config['dependency-upgrades']
        self.assertEqual(upgrades['npm_projects'], [])  # an empty list turns detection off
        self.assertEqual(upgrades['pip_requirements'], ['requirements/base.txt'])

    def test_a_bad_file_is_still_an_error(self) -> None:
        self.write('mason.toml', 'version = 1\n[limits]\nopen_agnet_prs = 1\n')
        with self.assertRaisesRegex(project.ConfigError, 'open_agnet_prs: is not a known field'):
            project.resolve(self.repo)

    def test_undetectable_values_name_the_key(self) -> None:
        self.git('remote', 'set-url', 'origin', 'git@gitlab.com:owner/repo.git')
        with self.assertRaisesRegex(project.ConfigError, r'\$\.repo\.name: is required'):
            project.load(self.repo)

    def test_unknown_section(self) -> None:
        with self.assertRaisesRegex(project.ConfigError, r'no such section \[deploy\]'):
            project.load(self.repo, 'deploy')

    def test_nothing_to_upgrade(self) -> None:
        self.git('rm', '-q', 'requirements/base.txt', 'package-lock.json', 'web/package-lock.json')
        with self.assertRaisesRegex(project.ConfigError, 'found no compiled requirements'):
            project.load(self.repo, 'dependency-upgrades')

    def test_refusal_names_the_unsupported_lockfiles(self) -> None:
        self.git('rm', '-q', 'requirements/base.txt', 'package-lock.json', 'web/package-lock.json')
        self.write('poetry.lock', '')
        self.git('add', 'poetry.lock')
        with self.assertRaisesRegex(project.ConfigError, 'Note: poetry.lock: not read'):
            project.load(self.repo, 'dependency-upgrades')

    def test_runs_are_kept_under_the_github_repository(self) -> None:
        self.assertEqual(detect.project_key(self.repo), 'owner__repo')

    def test_unsupported_lockfiles_are_noted(self) -> None:
        self.write('uv.lock', '')
        self.git('add', 'uv.lock')
        self.assertEqual(
            project.resolve(self.repo).notes,
            ['uv.lock: not read; dependency-upgrades supports pip-compile and npm'],
        )

    def test_toml_is_a_valid_starting_file(self) -> None:
        self.write('mason.toml', 'version = 1\n[limits]\nopen_agent_prs = 1\n')
        text = project.to_toml(project.resolve(self.repo))
        self.assertIn('# stale_after_days = 14', text)
        parsed = tomllib.loads(text)
        self.assertEqual(parsed['limits'], {'open_agent_prs': 1})
        self.assertEqual(parsed['version'], project.CONFIG_VERSION)
        uncommented = text.replace('# pip_compile = ', 'pip_compile = ')
        self.assertEqual(
            tomllib.loads(uncommented)['dependency-upgrades']['pip_compile'],
            'pip-compile requirements/base.in',
        )
        # The starting file it prints is itself a valid file.
        self.write('mason.toml', text)
        project.resolve(self.repo)

    def test_a_file_without_a_version_is_refused(self) -> None:
        self.write('mason.toml', '[limits]\nopen_agent_prs = 1\n')
        with self.assertRaisesRegex(project.ConfigError, 'has no `version`.*Set `version = 1`'):
            project.resolve(self.repo)

    def test_an_unknown_version_is_refused(self) -> None:
        for value in ('2', "'1'", '0'):
            self.write('mason.toml', f'version = {value}\n')
            with self.assertRaisesRegex(project.ConfigError, 'this mason reads version 1'):
                project.resolve(self.repo)

    def test_the_old_file_name_is_refused_with_how_to_move_it(self) -> None:
        self.write('.agents/automation.toml', '[limits]\nopen_agent_prs = 1\n')
        with self.assertRaisesRegex(
            project.ConfigError, 'now reads mason.toml at the project root'
        ):
            project.resolve(self.repo)

    def test_conventions_document_is_detected(self) -> None:
        self.assertEqual(project.resolve(self.repo).config['code-review']['conventions'], [])
        self.write('docs/conventions.md', '# Conventions\n')
        self.git('add', 'docs/conventions.md')
        resolved = project.resolve(self.repo)
        self.assertEqual(resolved.config['code-review']['conventions'], ['docs/conventions.md'])
        self.assertTrue(resolved.sources[('code-review', 'conventions')].startswith('detected: '))

    def test_cli(self) -> None:
        command = [sys.executable, '-I', str(SCRIPT), 'config', str(self.repo)]
        result = subprocess.run(
            [*command, '--section', 'dependency-upgrades'],
            capture_output=True,
            text=True,
            check=False,
        )
        self.assertEqual(result.returncode, 0, result.stderr)
        output = json.loads(result.stdout)
        expected = {'repo', 'limits', 'verify', 'dependency-upgrades', 'sources', 'notes'}
        self.assertEqual(set(output), expected)
        self.assertEqual(output['sources']['limits.open_agent_prs'], 'default')


if __name__ == '__main__':
    unittest.main()
